def is_balanced_A(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

def is_balanced_B(s):
    return (s.count('(') == s.count(')') and
            s.count('[') == s.count(']') and
            s.count('{') == s.count('}'))

def mystery(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo < hi:
        s = arr[lo] + arr[hi]
        if s == target:
            return True
        elif s < target:
            lo += 1
        else:
            hi -= 1
    return False

def is_sorted(nums):
    for i in range(len(nums) - 1):
        if nums[i] < nums[i + 1]:
            return True
    return False
